import { MarkdownPageEvent } from 'typedoc-plugin-markdown';

/**
 * Adds the title required by Fumadocs to every page generated by TypeDoc.
 *
 * @param {import('typedoc-plugin-markdown').MarkdownApplication} app
 */
export function load(app) {
  app.renderer.on(MarkdownPageEvent.BEGIN, (page) => {
    const modelName = page.model?.name;
    const isProjectIndex = page.model === page.project;

    page.frontmatter = {
      ...page.frontmatter,
      title: isProjectIndex || !modelName ? 'TypeScript API' : modelName,
    };
  });

  app.renderer.on(MarkdownPageEvent.END, (page) => {
    // TypeDoc links to generated source filenames. Fumadocs exposes the same
    // documents as extensionless routes, so `.mdx` would lead to a browser 404.
    page.contents = page.contents.replace(
      /(\]\()([^\s)#?]+)\.mdx((?:[?#][^)]*)?\))/g,
      (_match, opening, filePath, closing) => {
        const routePath = filePath === 'index'
          ? '.'
          : filePath.endsWith('/index')
            ? filePath.slice(0, -'/index'.length)
            : filePath;

        return `${opening}${routePath}${closing}`;
      },
    );
  });
}
